struct book { long id, author_id; struct author *author; int author_loaded; };

struct author *book_author(struct book *b) {
    if (!b->author_loaded) {                    /* first touch */
        b->author = author_find(b->author_id);  /* NULL = row absent */
        b->author_loaded = 1;
    }
    return b->author;
}
